use std::time::Duration;

use tokio_util::sync::CancellationToken;
use tokio_util::task::TaskTracker;

async fn poll_queue(name: &'static str, token: CancellationToken) {
    loop {
        println!("{name}: polling");
        tokio::select! {
            _ = token.cancelled() => break,
            _ = tokio::time::sleep(Duration::from_secs(30)) => {}
        }
    }
    println!("{name}: stopped");
}

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let token = CancellationToken::new();
    let tracker = TaskTracker::new();
    for name in ["billing", "mailer", "reports"] {
        tracker.spawn(poll_queue(name, token.clone()));
    }
    tokio::signal::ctrl_c().await?;
    token.cancel();
    tracker.wait().await;
    Ok(())
}

use tokio::signal::unix::{SignalKind, signal};

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let token = CancellationToken::new();
    let tracker = TaskTracker::new();
    let mailer = token.child_token();
    tracker.spawn(poll_queue("billing", token.clone()));
    tracker.spawn(poll_queue("mailer", mailer.clone()));
    tracker.spawn(poll_queue("reports", token.clone()));

    let mut usr1 = signal(SignalKind::user_defined1())?;
    tokio::spawn(async move {
        usr1.recv().await;
        mailer.cancel();
    });

    tracker.close();
    tokio::signal::ctrl_c().await?;
    token.cancel();
    tracker.wait().await;
    Ok(())
}
